    "C": "Vrai. Mesures hygiéno-diététiques.",
    "D": "Vrai. Les uricoinhibiteurs.",
    "E": "Vrai. Les uricosuriques.",
    "_synthese": "Traitement de fond de la goutte : hygiène de vie, uricoinhibiteurs ou uricosuriques."
