    "E": "Vrai. Une limitation de l’abduction est un signe clinique.",
    "_synthese": "Facteurs de risque de luxation congénitale : sexe féminin, primiparité, siège, gémellité, malformations des pieds, antécédents familiaux, limitation de l’abduction."
