  "otr-691": {
    "A": "Faux. L’ostéosarcome est bien la tumeur primitive maligne la plus fréquente.",
    "B": "Faux. La tumeur maligne osseuse la plus fréquente est la métastase.",
    "C": "Vrai (affirmation erronée). Le sarcome d’Ewing est de pronostic sévère.",
    "D": "Vrai (affirmation erronée). Les tumeurs à cellules géantes peuvent être agressives.",
    "E": "Vrai (affirmation erronée). Le chondrosarcome produit une matrice chondroïde, sans ostéoïde.",
    "_synthese": "Affirmations vraies : ostéosarcome le plus fréquent des primitifs, métastases les plus fréquentes."
  },
